def find_order(a, m):
    # Find the order of a modulo m
    # Only works if gcd(a, m) == 1
    import math
    if math.gcd(a, m) != 1:
        return None

    phi = 0
    # Calculation of phi(m)
    # For 10000 = 2^4 * 5^4, phi = 10000 * (1 - 1/2) * (1 - 1/5) = 4000
    # We can just use a simple loop if m is small or use a more general formula
    def get_phi(n):
        res = n
        p = 2
        temp = n
        while p * p <= temp:
            if temp % p == 0:
                while temp % p == 0:
                    temp //= p
                res -= res // p
            p += 1
        if temp > 1:
            res -= res // temp
        return res

    phi_m = get_phi(m)

    # The order k divides phi_m
    # Find all divisors of phi_m
    divisors = []
    for i in range(1, int(phi_m**0.5) + 1):
        if phi_m % i == 0:
            divisors.append(i)
            if i*i != phi_m:
                divisors.append(phi_m // i)
    divisors.sort()

    for d in divisors:
        if pow(a, d, m) == 1:
            return d
    return None

